const KONTEXTE = ["privat", "arbeitgeber_visolva"];
const alle = $input.all();
if (alle.length !== 1) {
  throw new Error("action_classify_invalid_input: genau ein Aufruf je Ausfuehrung erwartet, erhalten " + alle.length);
}
const e = alle[0].json;
if (KONTEXTE.indexOf(e.context_id) === -1) {
  throw new Error("action_classify_invalid_input: context_id nicht im Register");
}
if (!e.action_type) {
  throw new Error("action_classify_invalid_input: action_type fehlt");
}
if (!/^[a-z][a-z0-9_]*\.[a-z][a-z0-9_]*$/.test(String(e.tool_id || ""))) {
  throw new Error("action_classify_invalid_input: tool_id fehlt oder ist ungueltig");
}
if (!/^[0-9]+\.[0-9]+\.[0-9]+$/.test(String(e.tool_version || ""))) {
  throw new Error("action_classify_invalid_input: tool_version fehlt oder ist ungueltig");
}
const hoch = e.manual_escalation ? String(e.manual_escalation) : "";
if (hoch && ["A", "B", "C"].indexOf(hoch) === -1) {
  throw new Error("action_classify_invalid_input: manual_escalation unzulaessig");
}
return [{ json: {
  context_id: e.context_id,
  action_type: String(e.action_type),
  tool_id: e.tool_id,
  tool_version: e.tool_version,
  manual_escalation: hoch,
  trace_id: e.trace_id || null
} }];

// Risikoklasse = Maximum aus Registerwert, Kontextregel, Aussenwirkungsregel und manueller Hochstufung.
// Eine Herabstufung ist nicht moeglich. Unbekanntes Werkzeug faellt auf C (fail closed).
const RANG = { A: 1, B: 2, C: 3 };
const e = $('Eingabe pruefen').first().json;
const r = $input.first().json;
let klasse;
let quelle;
let grund = "";
if (r.found !== true) {
  klasse = "C";
  quelle = "rule";
  grund = "tool_not_registered_fail_closed";
} else {
  klasse = r.registry_class;
  quelle = "tool_default";
  if (r.override_class && RANG[r.override_class] > RANG[klasse]) {
    klasse = r.override_class;
    quelle = "context_override";
  }
  const ext = r.external_effect;
  const extMin = (ext === "financial" || ext === "legal") ? "C" : (ext === "external_recipient" ? "B" : null);
  if (extMin && RANG[extMin] > RANG[klasse]) {
    klasse = extMin;
    quelle = "rule";
    grund = "external_effect_" + ext;
  }
}
if (e.manual_escalation && RANG[e.manual_escalation] > RANG[klasse]) {
  klasse = e.manual_escalation;
  quelle = "manual_escalation";
}
return [{ json: {
  risk_class: klasse,
  risk_class_source: quelle,
  approval_required: klasse === "C",
  registered: r.found === true,
  tool_status: r.tool_status || null,
  context_allowed: r.context_allowed === true,
  registry_class: r.registry_class || null,
  reason: grund,
  action_type: e.action_type,
  tool_id: e.tool_id,
  tool_version: e.tool_version,
  context_id: e.context_id,
  trace_id: e.trace_id
} }];
